const int INF = 1e17 + 7;
const int MAXN = 1001;

int dir_x[]{0, 0, -1, 1}, dir_y[]{-1, 1, 0, 0};
vector<int> adj[MAXN];
bool visited[MAXN];
int match[MAXN];

bool is_valid(int x, int y, const vector<string>& grid) {
    int n = (int)grid.size();
    return x >= 0 && y >= 0 && x < n && y < n && grid[x][y] != 'Y' && grid[x][y] != 'Z';
}

vector<vector<int>> get_distances(int sx, int sy, const vector<string>& grid) {
    int n = (int)grid.size();
    vector<vector<int>> dist(n, vector<int>(n, INF));
    dist[sx][sy] = 0;
    deque<pii> q;
    q.push_back({sx, sy});
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop_front();
        for (int d = 0; d < 4; d++) {
            int nx = x + dir_x[d], ny = y + dir_y[d];
            if (!is_valid(nx, ny, grid) || dist[nx][ny] != INF) continue;
            dist[nx][ny] = dist[x][y] + 1;
            q.push_back({nx, ny});
        }
    }
    return dist;
}

void build_graph() {
    int n, t;
    cin >> n >> t;
    vector<string> s1(n), s2(n);
    for (int i = 0; i < n; i++) cin >> s1[i];
    for (int i = 0; i < n; i++) cin >> s2[i];

    int rx = -1, ry = -1;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (s1[i][j] == 'Z') {
                rx = i;
                ry = j;
            }
        }
    }

    vector<vector<int>> reac_dist = get_distances(rx, ry, s1);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!is_valid(i, j, s1)) continue;
            vector<vector<int>> from_cell = get_distances(i, j, s1);
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (!is_valid(x, y, s1) || from_cell[x][y] > t || from_cell[x][y] > reac_dist[x][y]) continue;
                    if (from_cell[x][y] == reac_dist[x][y]) {
                        bool can_move = false;
                        for (int dir_idx = 0; dir_idx < 4; dir_idx++) {
                            int xto = x + dir_x[dir_idx];
                            int yto = y + dir_y[dir_idx];
                            if (!is_valid(xto, yto, s1) || from_cell[xto][yto] >= reac_dist[xto][yto]) continue;
                            can_move = true;
                        }
                        if (!can_move) continue;
                    }
                    int max1 = s1[i][j] - '0';
                    int max2 = s2[x][y] - '0';
                    for (int num1 = 1; num1 <= max1; num1++) {
                        for (int num2 = 1; num2 <= max2; num2++) {
                            int v1 = 10 * (j + i * 10) + num1;
                            int v2 = 10 * (y + 10 * x) + num2;
                            adj[v1].push_back(v2);
                        }
                    }
                }
            }
        }
    }
}

bool dfs(int v) {
    if (visited[v]) return false;
    visited[v] = true;
    for (int to : adj[v]) {
        if (match[to] == 0 || dfs(match[to])) {
            match[to] = v;
            return true;
        }
    }
    return false;
}

